import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.DYPTBNgj.js";const k=JSON.parse('{"title":"Day-to-day operation","description":"","frontmatter":{},"headers":[],"relativePath":"operations/index.md","filePath":"operations/index.md","lastUpdated":null}'),n={name:"operations/index.md"};function o(h,s,r,l,p,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="day-to-day-operation" tabindex="-1">Day-to-day operation <a class="header-anchor" href="#day-to-day-operation" aria-label="Permalink to &quot;Day-to-day operation&quot;">​</a></h1><h2 id="check-the-service" tabindex="-1">Check the service <a class="header-anchor" href="#check-the-service" aria-label="Permalink to &quot;Check the service&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-fJdkw" id="tab-p6m8HVd" checked><label data-title="Linux / systemd" for="tab-p6m8HVd">Linux / systemd</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div></div></div><p>The daemon logs to the system journal when run by systemd.</p><h2 id="view-status" tabindex="-1">View status <a class="header-anchor" href="#view-status" aria-label="Permalink to &quot;View status&quot;">​</a></h2><p>Show one current status snapshot:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>In a terminal, status is formatted for reading. Redirected output is one JSON object. Watch continuously:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --interval</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5s</span></span></code></pre></div><p>When watch output is redirected, it becomes newline-delimited JSON.</p><h2 id="request-a-snapshot" tabindex="-1">Request a snapshot <a class="header-anchor" href="#request-a-snapshot" aria-label="Permalink to &quot;Request a snapshot&quot;">​</a></h2><p>Queue an immediate snapshot for every active root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span></span></code></pre></div><p>Or name one or more active scheduling roots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span></code></pre></div><p>A trigger uses the normal queue and safety checks. It does not duplicate work that is already queued or running.</p><h2 id="confirm-that-protection-is-current" tabindex="-1">Confirm that protection is current <a class="header-anchor" href="#confirm-that-protection-is-current" aria-label="Permalink to &quot;Confirm that protection is current&quot;">​</a></h2><p>Use all three views:</p><ol><li><code>boomerangz status</code> to confirm the daemon and recent work;</li><li><code>boomerangz dataset inspect DATASET</code> to confirm the effective policy;</li><li><code>zfs list -t snapshot -r DATASET</code> on the source and <code>zfs list -r ROOT</code> on each destination to confirm the stored data.</li></ol><p>For remote destinations, confirm both the most recent successful transfer and the destination dataset itself. A successful source snapshot alone does not prove that an independent copy exists.</p><h2 id="apply-configuration-changes" tabindex="-1">Apply configuration changes <a class="header-anchor" href="#apply-configuration-changes" aria-label="Permalink to &quot;Apply configuration changes&quot;">​</a></h2><p>After editing configuration files, apply them without interrupting active work:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-jtAAD" id="tab-ooZwCor" checked><label data-title="Linux / systemd" for="tab-ooZwCor">Linux / systemd</label><input type="radio" name="group-jtAAD" id="tab-TZycdZp"><label data-title="Direct command" for="tab-TZycdZp">Direct command</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div></div></div><p>The direct command&#39;s JSON result identifies fields applied live and any <code>restart_required</code> fields retained from the previous configuration. The systemd action writes the same result to the service journal. An invalid or otherwise unusable candidate leaves the running configuration unchanged and causes the reload action to fail. See <a href="/guide/configuration#validate-changes">Configure the daemon</a> for the reload contract and non-default socket usage.</p><p>Only restart the service when the reload result requires it, such as after changing <code>paths.identity_dir</code>, or when performing planned maintenance. Stopping the daemon prevents new work and cancels active transfers; recoverable transfer state is retained so work can continue after restart.</p><h2 id="monitor-storage" tabindex="-1">Monitor storage <a class="header-anchor" href="#monitor-storage" aria-label="Permalink to &quot;Monitor storage&quot;">​</a></h2><p>Review source snapshots and destination usage regularly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name,used,available,refer,mountpoint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name,used,refer,creation</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creation</span></span></code></pre></div><p>Retention limits snapshot history, but snapshots can remain because another ZFS object or an incomplete replication still depends on them. Investigate rather than deleting unfamiliar state manually.</p>`,29)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
